correct_example.code:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IPredicate {
    function deposit(address token, address user, uint256 amount, bytes calldata data) external;
}

contract Bridge {
    mapping(uint256 => address) public predicateRegistry; // tokenType => predicate

    event PredicateRegistered(uint256 indexed tokenType, address indexed predicate);

    function setPredicate(uint256 tokenType, address predicate) external onlyOwner {
        predicateRegistry[tokenType] = predicate;
        emit PredicateRegistered(tokenType, predicate);
    }

    function depositERC20(address token, uint256 amount, bytes calldata data) external {
        address predicate = predicateRegistry[1]; // 1 = ERC20
        require(predicate != address(0), "predicate not set");
        IPredicate(predicate).deposit(token, msg.sender, amount, data);
    }

    function depositERC721(address token, uint256 tokenId, bytes calldata data) external {
        address predicate = predicateRegistry[2]; // 2 = ERC721
        require(predicate != address(0), "predicate not set");
        IPredicate(predicate).deposit(token, msg.sender, tokenId, data);
    }
}
